using System.Text.Json;
using System.Text.RegularExpressions;
using AppBackendBasic.Core.DTOs;
using AppBackendBasic.Services.Captions;
using Xunit;

namespace AppBackendBasic.Captions.Tests;

/// <summary>
/// Asserts the C# port reproduces the ORIGINAL Python backend's output exactly. The fixture is generated by
/// scripts/old-sync/generate_golden.py from the old repo; regenerate it whenever the old caption logic changes.
/// </summary>
public class GoldenParityTests
{
    private static readonly JsonElement Golden = JsonDocument.Parse(
        File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "golden", "golden.json"))).RootElement;

    private static readonly JsonSerializerOptions Opts = new() { PropertyNameCaseInsensitive = true };

    private static List<CaptionWordDto> Words(JsonElement arr) =>
        JsonSerializer.Deserialize<List<CaptionWordDto>>(arr.GetRawText(), Opts)!;

    private static string NormNum(string s) => Regex.Replace(s, @"(\d+)\.0\b", "$1");

    [Fact]
    public void DifflibRatio_matches_python()
    {
        foreach (var c in Golden.GetProperty("ratio").EnumerateArray())
            Assert.Equal(c.GetProperty("ratio").GetDouble(),
                DifflibRatio.Ratio(c.GetProperty("a").GetString()!.ToLowerInvariant(), c.GetProperty("b").GetString()!.ToLowerInvariant()), 12);
    }

    [Fact]
    public void Tokens_and_repetition_match_python()
    {
        foreach (var c in Golden.GetProperty("tokens").EnumerateArray())
        {
            var tokens = TranscriptionAlgorithms.Tokens(c.GetProperty("text").GetString()!);
            Assert.Equal(c.GetProperty("tokens").EnumerateArray().Select(x => x.GetString()), tokens);
            var m = TranscriptionAlgorithms.RepetitionMetricsFor(tokens);
            var e = c.GetProperty("metrics");
            Assert.Equal(e.GetProperty("unique_ratio").GetDouble(), m.UniqueRatio, 12);
            Assert.Equal(e.GetProperty("bigram_ratio").GetDouble(), m.BigramRatio, 12);
            Assert.Equal(e.GetProperty("ngram_repeat").GetInt32(), m.NgramRepeat);
            Assert.Equal(e.GetProperty("penalty").GetDouble(), m.Penalty, 12);
        }
    }

    [Fact]
    public void Alignment_and_stitching_match_python()
    {
        var aligns = Golden.GetProperty("align").EnumerateArray().ToList();
        var stitches = Golden.GetProperty("stitch").EnumerateArray().ToList();
        for (int i = 0; i < stitches.Count; i++)
        {
            var wh = aligns[i].GetProperty("whisper").EnumerateArray().Select(x => x.GetString()!).ToList();
            var sa = aligns[i].GetProperty("sarvam").EnumerateArray().Select(x => x.GetString()!).ToList();
            var ops = TranscriptionAlgorithms.AlignWords(wh, sa);
            var expected = aligns[i].GetProperty("ops").EnumerateArray().ToList();
            Assert.Equal(expected.Count, ops.Count);
            for (int k = 0; k < ops.Count; k++)
            {
                var e = expected[k];
                var kind = e[0].GetString();
                Assert.Equal(kind == "match" ? AlignKind.Match : kind == "skip_whisper" ? AlignKind.SkipWhisper : AlignKind.SkipSarvam, ops[k].Kind);
                if (kind == "match") { Assert.Equal(e[1].GetInt32(), ops[k].WhisperIndex); Assert.Equal(e[2].GetInt32(), ops[k].SarvamIndex); }
                else if (kind == "skip_whisper") Assert.Equal(e[1].GetInt32(), ops[k].WhisperIndex);
                else Assert.Equal(e[1].GetInt32(), ops[k].SarvamIndex);
            }

            var whisperWords = Words(stitches[i].GetProperty("whisper"));
            var result = TranscriptionAlgorithms.StitchChunk(whisperWords, stitches[i].GetProperty("sarvam").GetString()!);
            var exp = stitches[i].GetProperty("result").EnumerateArray().ToList();
            Assert.Equal(exp.Count, result.Count);
            for (int k = 0; k < exp.Count; k++)
            {
                Assert.Equal(exp[k].GetProperty("original").GetString(), result[k].Original);
                Assert.Equal(exp[k].GetProperty("start").GetDouble(), result[k].Start, 9);
                Assert.Equal(exp[k].GetProperty("end").GetDouble(), result[k].End, 9);
            }
        }
    }

    [Fact]
    public void ChunkBoundaries_and_silence_match_python()
    {
        foreach (var c in Golden.GetProperty("chunks").EnumerateArray())
        {
            var sil = c.GetProperty("silence").EnumerateArray().Select(x => x.GetDouble()).ToList();
            var result = TranscriptionAlgorithms.ChunkBoundaries(c.GetProperty("total").GetDouble(), sil, c.GetProperty("seconds").GetInt32(), c.GetProperty("snap").GetDouble());
            Assert.Equal(c.GetProperty("result").EnumerateArray().Select(x => x.GetDouble()), result);
        }
        var s = Golden.GetProperty("silence_midpoints");
        Assert.Equal(s.GetProperty("result").EnumerateArray().Select(x => x.GetDouble()), TranscriptionAlgorithms.SilenceMidpoints(s.GetProperty("stderr").GetString()!));
    }

    [Fact]
    public void NormalizeTimings_matches_python()
    {
        var n = Golden.GetProperty("normalize");
        var words = Words(n.GetProperty("input"));
        TranscriptionAlgorithms.NormalizeWordTimings(words);
        var exp = n.GetProperty("result").EnumerateArray().ToList();
        for (int i = 0; i < words.Count; i++)
        {
            Assert.Equal(exp[i].GetProperty("start").GetDouble(), words[i].Start, 9);
            Assert.Equal(exp[i].GetProperty("end").GetDouble(), words[i].End, 9);
        }
    }

    [Fact]
    public void WhisperCandidate_matches_python()
    {
        foreach (var c in Golden.GetProperty("whisper").EnumerateArray())
        {
            var r = TranscriptionAlgorithms.BuildWhisperCandidate(c.GetProperty("response"), c.GetProperty("skip").GetDouble());
            var e = c.GetProperty("result");
            Assert.Equal(e.GetProperty("trustworthy").GetBoolean(), r.Trustworthy);
            Assert.Equal(e.GetProperty("average_logprob").GetDouble(), r.AverageLogprob, 9);
            var ew = e.GetProperty("words").EnumerateArray().ToList();
            Assert.Equal(ew.Count, r.Words.Count);
            for (int i = 0; i < ew.Count; i++)
            {
                Assert.Equal(ew[i].GetProperty("original").GetString(), r.Words[i].Original);
                Assert.Equal(ew[i].GetProperty("start").GetDouble(), r.Words[i].Start, 9);
                Assert.Equal(ew[i].GetProperty("end").GetDouble(), r.Words[i].End, 9);
            }
        }
    }

    [Fact]
    public void Grouping_matches_python()
    {
        var words = Words(Golden.GetProperty("ass").GetProperty("words"));
        foreach (var c in Golden.GetProperty("group").EnumerateArray())
        {
            int? n = c.GetProperty("words_per_caption").ValueKind == JsonValueKind.Null ? null : c.GetProperty("words_per_caption").GetInt32();
            var groups = CaptionLayout.GroupWordsForDisplay(words, minDisplay: c.GetProperty("min_display").GetDouble(), maxWords: n ?? 3, strictCount: n != null);
            var exp = c.GetProperty("groups").EnumerateArray().Select(g => g.EnumerateArray().Select(x => x.GetInt32()).ToList()).ToList();
            Assert.Equal(exp, groups.Select(g => g.Select(w => w.Index).ToList()).ToList());
        }
    }

    [Fact]
